import { referenceTheme } from '../reference/vscode-dark-2026/generated'
import { builtinTokens } from '../generated/tokens'
import { isHexColor, themeRoles } from './contrast'
import { freezeOwned } from './types'
import type { RegisteredTheme, ThemeRegistry, ThemeIssue, ThemeKind, ThemeRole } from './types'

export const BUILTIN_IDS = Object.freeze({
  light: 'frade.builtin/light',
  dark: 'frade.builtin/dark',
  'high-contrast': 'frade.builtin/high-contrast',
})
export const themeKinds: readonly ThemeKind[] = Object.freeze(['light', 'dark', 'high-contrast'])
const labels: Record<ThemeKind, string> = {
  light: 'Frade Light',
  dark: 'Frade Dark',
  'high-contrast': 'Frade High Contrast',
}
const roles = new Set<string>(themeRoles)
export function isDataRecord(value: unknown): value is Record<string, unknown> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false
  const prototype = Object.getPrototypeOf(value)
  return (
    (prototype === Object.prototype || prototype === null) &&
    Object.values(Object.getOwnPropertyDescriptors(value)).every((d) => 'value' in d)
  )
}
export function issue(code: string, source: string, message: string, role?: string): ThemeIssue {
  return role === undefined ? { code, source, message } : { code, source, message, role }
}
/** Native descriptors accept data only. This is an in-memory registry, not an installer. */
export function validateColors(
  value: unknown,
  source: string,
): {
  colors: Partial<Record<ThemeRole, string>>
  issues: ThemeIssue[]
  recognized: string[]
  ignored: string[]
} {
  const colors: Partial<Record<ThemeRole, string>> = {},
    issues: ThemeIssue[] = [],
    recognized: string[] = [],
    ignored: string[] = []
  if (!isDataRecord(value))
    return {
      colors,
      issues: [issue('INVALID_COLORS', source, 'Colors must be a plain data record')],
      recognized,
      ignored,
    }
  for (const role of themeRoles)
    if (Object.hasOwn(value, role)) {
      if (isHexColor(value[role])) {
        colors[role] = value[role]
        recognized.push(role)
      } else {
        issues.push(issue('INVALID_COLOR', source, 'Known roles require HEX6 values', role))
        ignored.push(role)
      }
    }
  for (const role of Object.keys(value)
    .filter((key) => !roles.has(key))
    .sort()) {
    issues.push(issue('UNKNOWN_ROLE', source, 'Unregistered role ignored', role))
    ignored.push(role)
  }
  return { colors, issues, recognized, ignored }
}
export function createThemeRegistry(descriptors: readonly unknown[] = []): ThemeRegistry {
  const entries = new Map<string, RegisteredTheme>(),
    issues: ThemeIssue[] = []
  for (const kind of themeKinds)
    entries.set(
      BUILTIN_IDS[kind],
      freezeOwned({
        id: BUILTIN_IDS[kind],
        label: labels[kind],
        kind,
        enabled: true,
        builtin: true,
        colors: { ...builtinTokens.themes[kind] },
        issues: [],
      }),
    )
  for (const [index, descriptor] of descriptors.entries()) {
    const source = 'descriptor[' + index + ']'
    if (!isDataRecord(descriptor)) {
      issues.push(issue('INVALID_DESCRIPTOR', source, 'Theme must be a plain data record'))
      continue
    }
    if (typeof descriptor.id === 'string' && descriptor.id.startsWith('frade.builtin/')) {
      issues.push(issue('RESERVED_ID', source, 'Builtin identity cannot be replaced'))
      continue
    }
    if (
      typeof descriptor.id !== 'string' ||
      descriptor.id.length > 160 ||
      !/^[a-z0-9][a-z0-9.-]*\.[a-z0-9][a-z0-9.-]*[/][a-z0-9][a-z0-9._-]*$/i.test(descriptor.id) ||
      typeof descriptor.label !== 'string' ||
      descriptor.label.length < 1 ||
      descriptor.label.length > 160 ||
      [...descriptor.label].some(
        (character) => character.charCodeAt(0) < 32 || character.charCodeAt(0) === 127,
      ) ||
      !themeKinds.includes(descriptor.kind as ThemeKind) ||
      (descriptor.enabled !== undefined && typeof descriptor.enabled !== 'boolean') ||
      Object.keys(descriptor).some(
        (key) => !['id', 'label', 'kind', 'enabled', 'colors'].includes(key),
      ) ||
      !isDataRecord(descriptor.colors)
    ) {
      issues.push(
        issue('INVALID_DESCRIPTOR', source, 'Invalid theme identity, kind, label or data fields'),
      )
      continue
    }
    if (entries.has(descriptor.id)) {
      issues.push(issue('DUPLICATE_ID', source, 'First registered stable identity wins'))
      continue
    }
    const validated = validateColors(descriptor.colors, descriptor.id)
    issues.push(...validated.issues)
    entries.set(
      descriptor.id,
      freezeOwned({
        id: descriptor.id,
        label: descriptor.label,
        kind: descriptor.kind as ThemeKind,
        enabled: descriptor.enabled !== false,
        builtin: false,
        colors: validated.colors,
        issues: validated.issues,
      }),
    )
  }
  const list = freezeOwned([...entries.values()]),
    diagnostics = freezeOwned(issues)
  return Object.freeze({
    issues: diagnostics,
    get: (id: string) => entries.get(id),
    list: () => list,
  })
}

/** Application opt-in: the pure core registry's three-builtin contract stays unchanged. */
export function createApplicationThemeRegistry(descriptors: readonly unknown[] = []): ThemeRegistry {
  return createThemeRegistry([referenceTheme.descriptor, ...descriptors])
}

import { applyReferencePreset } from '../reference/vscode-dark-2026/profile'
import type { ResolvedTheme } from './types'
import { isHexColor, themeRoles } from './contrast'
import type {
  PresentationParticipant,
  PresentationBarrier,
  PhaseContext,
  PaintAck,
} from './service'
export interface RootParticipantOptions {
  readonly id?: string
  readonly generation?: number
  readonly paint?: () => Promise<void>
}
/** Two RAF boundaries: an ACK after the second observes the paint between them. */
export function afterPresentationPaint(root: HTMLElement): Promise<void> {
  const view = root.ownerDocument.defaultView
  if (!view) return Promise.reject(Error('Presentation document has no active view'))
  return new Promise((resolve) =>
    view.requestAnimationFrame(() => view.requestAnimationFrame(() => resolve())),
  )
}
const systemColor = (role: string): string =>
  [
    'action.primary',
    'action.primaryHover',
    'selection.bg',
    'selection.indicator',
    'focus.ring',
    'diagram.selection',
  ].includes(role)
    ? 'Highlight'
    : ['action.onPrimary', 'selection.fg'].includes(role)
      ? 'HighlightText'
      : role.startsWith('surface.') || role.endsWith('Bg') || role === 'diagram.canvas'
        ? 'Canvas'
        : 'CanvasText'
export function validatePresentationSnapshot(snapshot: ResolvedTheme): void {
  for (const values of [snapshot.colors, snapshot.effectiveColors])
    if (
      Object.keys(values).length !== themeRoles.length ||
      themeRoles.some((role) => !Object.hasOwn(values, role))
    )
      throw Error('Incomplete presentation role projection')
  for (const role of themeRoles)
    if (
      !isHexColor(snapshot.colors[role]) ||
      snapshot.effectiveColors[role] !==
        (snapshot.forcedColors ? systemColor(role) : snapshot.colors[role])
    )
      throw Error('Invalid presentation role projection: ' + role)
  if (
    !['light', 'dark', 'high-contrast'].includes(snapshot.kind) ||
    !['compact', 'comfortable'].includes(snapshot.density) ||
    !Number.isSafeInteger(snapshot.revision) ||
    snapshot.revision < 0
  )
    throw Error('Invalid presentation root metadata')
}
export function applyRootSnapshot(root: HTMLElement, snapshot: ResolvedTheme): void {
  validatePresentationSnapshot(snapshot)
  for (const role of themeRoles)
    root.style.setProperty('--frade-' + role.replaceAll('.', '-'), snapshot.effectiveColors[role])
  applyReferencePreset(root, snapshot)
  root.dataset.fradeRuntime = '1'
  root.dataset.fradeTheme = snapshot.kind
  root.dataset.fradeDensity = snapshot.density
  root.dataset.fradeRevision = String(snapshot.revision)
  root.style.colorScheme = snapshot.forcedColors
    ? 'light dark'
    : snapshot.kind === 'light'
      ? 'light'
      : 'dark'
}
export function createRootParticipant(
  root: HTMLElement,
  options: RootParticipantOptions = {},
): PresentationParticipant {
  const id = options.id ?? 'root',
    generation = options.generation ?? 1,
    paint = options.paint ?? (() => afterPresentationPaint(root))
  let hidden = false,
    visibility = '',
    priority = ''
  return {
    id,
    generation,
    hide: () => {
      if (hidden) return
      hidden = true
      visibility = root.style.getPropertyValue('visibility')
      priority = root.style.getPropertyPriority('visibility')
      root.style.setProperty('visibility', 'hidden')
    },
    reveal: () => {
      if (!hidden) return
      hidden = false
      if (visibility) root.style.setProperty('visibility', visibility, priority)
      else root.style.removeProperty('visibility')
    },
    prepare: async (snapshot, preparedContext, preparedSignal) => {
      validatePresentationSnapshot(snapshot)
      let disposed = false
      const valid = (context: PhaseContext, signal: AbortSignal, rollback: boolean) => {
        if (disposed || signal.aborted || (!rollback && preparedSignal.aborted))
          throw Error('Presentation root handle invalidated')
        if (
          !rollback &&
          (context.requestId !== preparedContext.requestId ||
            context.sessionId !== preparedContext.sessionId ||
            context.generation !== preparedContext.generation ||
            context.transactionId !== preparedContext.transactionId ||
            context.revision !== snapshot.revision ||
            context.membership !== preparedContext.membership)
        )
          throw Error('Presentation root phase mismatch')
        if (
          rollback
            ? context.phase !== 'rollback'
            : context.phase !== 'apply' && context.phase !== 'join' && context.phase !== 'rollback'
        )
          throw Error('Presentation root phase mismatch')
      }
      const ack = (context: PhaseContext): PaintAck =>
        Object.freeze({
          ...context,
          participantId: id,
          participantGeneration: generation,
          painted: true,
        })
      return {
        apply: async (context, signal) => {
          valid(context, signal, false)
          applyRootSnapshot(root, snapshot)
          await paint()
          valid(context, signal, false)
          return ack(context)
        },
        rollback: async (previous, context, signal) => {
          valid(context, signal, true)
          applyRootSnapshot(root, previous)
          await paint()
          valid(context, signal, true)
          return ack(context)
        },
        dispose: () => {
          disposed = true
        },
      }
    },
  }
}
/** Caller mounts this in the stable managed host and supplies the service recovery action. */
export function createPresentationBarrier(
  host: HTMLElement,
  paint: () => Promise<void> = () => afterPresentationPaint(host),
  recover?: () => Promise<unknown>,
): PresentationBarrier {
  const curtain = host.ownerDocument.createElement('div'),
    status = host.ownerDocument.createElement('span'),
    button = host.ownerDocument.createElement('button')
  curtain.className = 'frade-theme-commit-barrier'
  curtain.hidden = true
  curtain.setAttribute('role', 'status')
  curtain.setAttribute('aria-live', 'polite')
  curtain.setAttribute('aria-atomic', 'true')
  status.textContent = 'Обновление интерфейса…'
  button.type = 'button'
  button.textContent = 'Повторить'
  button.hidden = true
  button.disabled = !recover
  curtain.append(status, button)
  host.append(curtain)
  const inert = new Map<HTMLElement, boolean>()
  let previousFocus: HTMLElement | undefined
  const cover = () => {
    curtain.hidden = false
    const owner = host.closest<HTMLElement>('.ka-workbench') ?? host
    if (!inert.size)
      previousFocus =
        host.ownerDocument.activeElement instanceof HTMLElement
          ? host.ownerDocument.activeElement
          : undefined
    for (const child of owner.children)
      if (
        child instanceof HTMLElement &&
        child !== curtain &&
        child !== host &&
        !inert.has(child)
      ) {
        inert.set(child, child.hasAttribute('inert'))
        child.setAttribute('inert', '')
      }
  }
  button.addEventListener('click', async () => {
    if (!recover || button.disabled) return
    button.disabled = true
    try {
      await recover()
    } catch (error) {
      status.textContent =
        'Восстановление не выполнено: ' + (error instanceof Error ? error.message : String(error))
    } finally {
      button.disabled = !recover
    }
  })
  return {
    paint: async () => {
      cover()
      button.hidden = true
      status.textContent = 'Обновление интерфейса…'
      await paint()
    },
    reveal: () => {
      curtain.hidden = true
      for (const [element, wasInert] of inert) if (!wasInert) element.removeAttribute('inert')
      inert.clear()
      if (previousFocus?.isConnected) previousFocus.focus({ preventScroll: true })
      previousFocus = undefined
    },
    recovery: (message) => {
      cover()
      status.textContent = 'Интерфейс ожидает восстановления: ' + message
      button.hidden = false
      button.disabled = !recover
      if (recover) button.focus({ preventScroll: true })
    },
  }
}

import { referenceTheme } from './generated'
import { builtinTokens } from '../../generated/tokens'
import { contrastRatio } from '../../theme/contrast'
import type { ResolvedTheme, ThemeRole } from '../../theme/types'

interface Slot {
  readonly key: string
  readonly role: ThemeRole
  readonly raw: string
  readonly background?: string
  readonly minimum?: number
}
const slots: Readonly<Record<string, Slot>> = referenceTheme.slots
export interface ReferenceStyleProjection {
  readonly colors: Readonly<Record<string, string>>
  readonly repairs: readonly {
    readonly slot: string
    readonly original: string
    readonly effective: string
  }[]
}
function composite(raw: string, background?: string): string {
  let hex = raw.slice(1)
  if (hex.length < 5) hex = [...hex].map((char) => char + char).join('')
  if (hex.length === 6) return '#' + hex.toUpperCase()
  if (hex.length !== 8 || !background) throw Error('Unbound reference alpha')
  const alpha = parseInt(hex.slice(6), 16) / 255
  return (
    '#' +
    [0, 2, 4]
      .map((offset) =>
        Math.round(
          parseInt(hex.slice(offset, offset + 2), 16) * alpha +
            parseInt(background.slice(offset + 1, offset + 3), 16) * (1 - alpha),
        )
          .toString(16)
          .padStart(2, '0'),
      )
      .join('')
      .toUpperCase()
  )
}
/** First-party view projection, after the existing resolver; it never selects or persists a theme. */
export function projectReferenceStyles(snapshot: ResolvedTheme): ReferenceStyleProjection {
  if (snapshot.id !== referenceTheme.id || snapshot.forcedColors) return { colors: {}, repairs: [] }
  const colors: Record<string, string> = {},
    active = new Set<string>()
  const repairs: { slot: string; original: string; effective: string }[] = []
  const resolve = (name: string): string => {
    if (colors[name]) return colors[name]
    if (active.has(name) || !Object.hasOwn(slots, name))
      throw Error('Invalid reference style dependency')
    active.add(name)
    const slot = slots[name],
      background = slot.background ? resolve(slot.background) : undefined
    const roleChanged = snapshot.colors[slot.role] !== referenceTheme.descriptor.colors[slot.role]
    let color = roleChanged ? snapshot.colors[slot.role] : composite(slot.raw, background)
    if (background && slot.minimum && contrastRatio(color, background) < slot.minimum) {
      const original = color
      const replacement = [
        snapshot.colors[slot.role],
        builtinTokens.themes.dark[slot.role],
        builtinTokens.themes.dark['text.primary'],
        builtinTokens.themes.light['text.primary'],
      ].find((candidate) => contrastRatio(candidate, background) >= slot.minimum!)
      if (!replacement) throw Error('Reference style contrast cannot be established: ' + name)
      color = replacement
      repairs.push({ slot: name, original, effective: color })
    }
    active.delete(name)
    colors[name] = color
    return color
  }
  for (const name of Object.keys(slots)) resolve(name)
  return { colors: Object.freeze(colors), repairs: Object.freeze(repairs) }
}

export function applyReferencePreset(root: HTMLElement, snapshot: ResolvedTheme): void {
  if (snapshot.id !== referenceTheme.id || snapshot.forcedColors) {
    if (root.dataset.fradeReference === 'vscode-dark-2026') {
      root.removeAttribute('data-frade-reference')
      for (const name of Object.keys(slots)) root.style.removeProperty('--frade-vscode-' + name)
    }
    return
  }
  const projection = projectReferenceStyles(snapshot)
  for (const [name, color] of Object.entries(projection.colors))
    root.style.setProperty('--frade-vscode-' + name, color)
  root.dataset.fradeReference = 'vscode-dark-2026'
}

